'use strict';
const YEARS=[2026,2036,2046,2056];
const BANDS=[['0—14岁',0,15,'#a4c8b6'],['15—24岁',15,25,'#85b9ce'],['25—34岁',25,35,'#448ba7'],['35—44岁',35,45,'#386d83'],['45—59岁',45,60,'#183b37'],['60—69岁',60,70,'#edbd83'],['70—79岁',70,80,'#d88c54'],['80—89岁',80,90,'#b65c3b'],['90岁及以上',90,101,'#823a39']];
const FERTILITY={'1':'低生育','2':'稳定生育','3':'中生育','4':'高生育','5':'极高生育'},MIGRATION={'1':'迁移情景1','2':'迁移情景2','3':'稳定迁移情景3'};
const S={route:'map',province:'GD',city:'ALL',f:'2',m:'3',year:2046,period:0,metric:'oldPP',unit:'count',tab:'overview',how:'home',mapCode:'440000',view:'scenario',vitalRegion:'PROVINCE',vitalBasis:'resident',from:2016,to:2025,vitalMetric:'count'};
const cityMemory={GD:'ALL',HN:'ALL',GX:'ALL'},budgetDrafts={};let exportRows=[];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=1)=>Number(v).toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d});
const wan=v=>n(v/1e4)+'万';const signed=(v,d=1)=>(v>0?'+':v<0?'−':'')+n(Math.abs(v),d);const delta=v=>signed(v/1e4)+'万人';
const sum=(a,lo=0,hi=a.length)=>a.slice(lo,hi).reduce((s,v)=>s+v,0);
const province=()=>REGISTRY.provinces[S.province];const cities=()=>REGISTRY.cities.filter(c=>c.province===S.province);
const city=id=>id==='PRD'?{id:'PRD',province:'GD',name:'珠三角九市合计（旧研究）'}:REGISTRY.cities.find(c=>c.id===id);const chosenCities=()=>['ALL','PRD'].includes(S.city)?cities():[city(S.city)];
const regionName=()=>S.city==='ALL'?province().name+'全省（2025实际基线；后续为情景）':S.city==='PRD'?'珠三角九市合计（旧研究对照，非广东全省）':city(S.city).name;
function source(key){const s=REGISTRY.sources[key];return s?`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)} ↗</a><small class="source-note">${esc(s.note)}</small>`:'<span class="badge missing">来源未接入</span>';}
function ages(id,y,f=S.f,m=S.m){const p=id==='ALL'?province().modelId:id;return p==='Guangdong'?gdAges(y,f,m):p==='Hunan'?hnAges(y,f,m):p==='Guangxi'?gxAges(y,f,m):null;}
function stats(id,y,f=S.f,m=S.m){const a=ages(id,y,f,m);if(!a)return null;const bands=BANDS.map(([,lo,hi])=>sum(a,lo,hi)),needBands=bands.slice(5).map((v,i)=>v*REGISTRY.surveyRates[i]);return {year:y,ages:a,total:sum(a),bands,senior:sum(a,60),old:sum(a,65),oldest:sum(a,80),needBands,need:sum(needBands)};}
function periodData(id,i=S.period,f=S.f,m=S.m){const a=stats(id,YEARS[i],f,m),b=stats(id,YEARS[i+1],f,m);return {id,a,b,start:YEARS[i],end:YEARS[i+1],oldPP:(b.senior/b.total-a.senior/a.total)*100,needDelta:b.need-a.need,totalDelta:b.total-a.total};}
function rankings(i=S.period,metric=S.metric,f=S.f,m=S.m){return cities().map(c=>({...c,...periodData(c.id,i,f,m)})).sort((a,b)=>b[metric]-a[metric]||a.name.localeCompare(b.name,'zh'));}
function badge(c){return `<span class="badge ${c.staff.kind==='issue'?'warn':c.staff.kind==='unknown'?'missing':''}">${c.staff.kind==='issue'?'问题／政策信号':c.staff.kind==='historical'?'历史研究提示':'本地匹配证据不足'}</span>`;}
function title(en,heading,sub){return `<section class="intro"><div class="eyebrow">${esc(en)}</div><h1>${esc(heading)}</h1><p>${esc(sub)}</p></section>`;}
function warning(){if(S.province==='GX'&&S.city==='ALL')return '<div class="note warning"><b>2026—2056全部是以广西2025实际大组为约束的条件模拟，不是官方预测。</b>2025实测总人口和四组年龄边界用于锚定；细年龄由2020普查结构和年度自然变动重建，单岁结构并非官方发布。假设迁移残差包含统计差异，不能称为纯净迁移。'+source('gx2025')+'</div>';return `<div class="note warning"><b>四个阶段全部为研究情景，2026也不是实测。</b>原研究以2010为基期，未按最新人口校准；历史偏差与镜像版本差异仍保留。照护参考人数再套用全国固定困难率，不等于本地失能总数、入住需求或服务缺口。</div>`;}
function controls(includeCity=true){return `<div class="panel controls"><label>查看省份<select id="provinceSelect">${Object.entries(REGISTRY.provinces).map(([id,p])=>`<option value="${id}" ${S.province===id?'selected':''}>${p.name}全省 · 市级对照覆盖${p.scope}</option>`).join('')}</select></label>${includeCity?`<label>城市／地区<select id="citySelect"><option value="ALL" ${S.city==='ALL'?'selected':''}>${province().name}全省（最新2025基线）</option>${S.province==='GD'?`<option value="PRD" ${S.city==='PRD'?'selected':''}>珠三角九市合计（旧研究，非全省）</option>`:''}${cities().map(c=>`<option value="${c.id}" ${S.city===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label>`:''}<label>生育情景<select id="fertility">${Object.entries(FERTILITY).map(([k,v])=>`<option value="${k}" ${S.f===k?'selected':''}>${hnLabels('fertility',k)}</option>`).join('')}</select></label><label>迁移情景<select id="migration">${Object.entries(MIGRATION).map(([k,v])=>`<option value="${k}" ${S.m===k?'selected':''}>${hnLabels('migration',k)}</option>`).join('')}</select></label></div>`+(["population","care"].includes(S.route)?scenarioNotes():`<details class="scenario-fold"><summary>当前研究假设：${hnLabels("fertility",S.f)} ／ ${hnLabels("migration",S.m)} · 展开参数与来源</summary>${scenarioNotes()}</details>`);}
function scenarioNotes(provId=S.province,cityId=S.city){if(provId==='GX'&&cityId==='ALL')return '<div class="note gx-method"><b>广西全区 · 最新实际基线队列条件模拟</b><p>2025年末常住人口4989万人；2020七普按年龄性别启动，结合2021—2024年人口平衡和2024年鉴年龄结构，按2025官方年龄大组重建细年龄。15岁约82万人是1073万（0—15岁）减991万（0—14岁）所得，属差额推算。</p><p>生育：'+esc(GX_FERTILITY[S.f].label)+'；以2025年36万出生校准2020普查年龄别生育曲线，到2036线性达到基线的'+n(GX_FERTILITY[S.f].target*100,0)+'%，之后保持；不是官方总和生育率或政策预测。</p><p>人口平衡残差：'+esc(GX_MOVEMENT[S.m].label)+'，约'+signed(GX_MOVEMENT[S.m].annual/1e4,2)+'万人／年。2025总人口较2024减少约24万人，其中出生减死亡为−4.5万人，剩余−19.5万人是迁移与统计调整合成差额，不能当作实测净迁移。</p><p>死亡：用2020普查年龄性别死亡数与人口构造近似年龄死亡强度，再按2025死亡40.5万人校准，未来保持不变；没有假设未来寿命改善。四阶段值均为模拟，2026也不是全年实际。</p><p>'+source('gxcensus')+' '+source('gxyearbook04')+' '+source('gxyearbook02')+' '+source('gx2025')+'</p></div>';if(provId==='GD'&&cityId==='ALL')return gdScenarioNotes();if(provId==='HN'&&cityId==='ALL')return hnScenarioNotes();const pInfo=REGISTRY.provinces[provId];
 const targets={'1':[.7,.9],'2':[1.3,1.3],'3':[1.5,1.8],'4':[1.8,1.8],'5':[1.8,2.1]},[a,b]=targets[S.f];
 const adjustment={tier1:[100,50,0],newTier1:[75,25,0],tier2:[50,0,0],other:[-75,-25,0]},labels={tier1:'一线（广州、深圳）',newTier1:'研究分类中的新一线（长沙、东莞、佛山）',tier2:'研究分类中的二线（惠州、珠海、中山）',other:'研究分类中的三线及其他城市'},group=id=>['Guangzhou','Shenzhen'].includes(id)?'tier1':['Changsha','Dongguan','Foshan'].includes(id)?'newTier1':['Huizhou','Zhuhai','Zhongshan'].includes(id)?'tier2':'other',fmt=v=>v===0?'保持2010年净迁移率':`${v>0?'加上':'减去'}2010年净迁移率绝对值的${Math.abs(v)}%`,i=Number(S.m)-1,prov=(provId==='GD'?1:-1)*[50,25,0][i];
 const groups=['ALL','PRD'].includes(cityId)?Object.keys(labels):[group(cityId)];
 return `<section class="scenario-notes" aria-label="当前情景假设说明"><div class="two"><article><h3>生育：${FERTILITY[S.f]} · 研究假设</h3><p>${S.f==='2'?'全国总和生育率保持1.3至2100年。':`全国总和生育率到2050年为${a}，到2100年为${b}。`}</p><small>总和生育率：按某时期各年龄生育率计算，一名女性一生平均生育的孩子数；不是出生率（‰），也不是当前城市实际水平。城市结果还取决于育龄女性数量和年龄分布。</small><p class="links"><a target="_blank" rel="noopener" href="https://www.nature.com/articles/s41597-023-02735-6/tables/2">原研究表2：生育参数 ↗</a></p></article><article><h3>迁移：情景${S.m} · 研究假设</h3><p><b>${pInfo.name}省级层面：</b>${fmt(prov)}。</p><ul>${groups.map(g=>`<li>${cityId==='ALL'?labels[g]:city(cityId).name+'（'+labels[g]+'）'}：${fmt(adjustment[g][i])}。</li>`).join('')}</ul><small>这是研究设置的2020年迁移参数，相对于2010年基准；不是2026或2056的实际迁移率，不表示总人口按此比例增减，也不是每年重复上调。人口迁移指迁入与迁出，不是出生与死亡。</small><p class="links"><a target="_blank" rel="noopener" href="https://www.nature.com/articles/s41597-023-02735-6/tables/3">表3：省级参数 ↗</a> · <a target="_blank" rel="noopener" href="https://www.nature.com/articles/s41597-023-02735-6/tables/4">表4：城市参数 ↗</a></p></article></div><details><summary>怎样理解参数、后续调整及对养老的影响</summary><p>净迁移率可正可负。例如基准为−1%，再减去其绝对值的50%，结果为−1.5%，不是流出减少50%。净迁移率为+1%，再加上其绝对值的100%，结果为+2%，不是全市人口翻倍。</p><p>原研究还包含迁移的年度路径、省际与市级平衡、城市规模和人口上限政策调整。上方只解释原研究参数；APP直接读取其结果，没有用注释中的比例重新计算各年人口。生育情景2／迁移情景3是原研究的基准组合，不表示今天最可信或最可能发生。</p><p>生育主要先改变儿童、随后改变劳动年龄人口；迁移会改变城市人数和年龄结构。养老图表随人口情景联动，但仍套用固定全国自理困难率，不能据此认定本地真实失能人数或服务缺口。历史出生死亡数据不受这些选项影响。</p><a target="_blank" rel="noopener" href="https://www.nature.com/articles/s41597-023-02735-6">原研究方法与限制 ↗</a><p class="hint">2023年研究，2010年基期；未按最新统计校准。表4的城市分类为原研究分类，不代表当前商业城市排名。</p></details></section>`;
}
const BASIS={resident:'常住人口',hukou:'户籍人口',unspecified:'口径未明确'};
const finite=v=>typeof v==='number'&&Number.isFinite(v);
const vf=(v,sign=false)=>finite(v)?(sign?signed(v,2):n(v,2)):'—';
const fullCounts=r=>r&&finite(r.birth)&&finite(r.death);
const directCounts=r=>fullCounts(r)&&!r.flagged&&!r.sourceComputed&&['official','official_account'].includes(VITAL.sources[r.source].kind);
const vstatus=r=>!r?'未取得':r.flagged?(r.year===2017&&['Changsha','Shaoyang'].includes(r.region)?'往年死亡集中销户':'原文待核'):r.sourceComputed?'原表公式推算':fullCounts(r)?'出生死亡人数齐':finite(r.birth)||finite(r.death)?'人数仅部分':'仅公布率';
const vitalRegionName=()=>S.vitalRegion==='PROVINCE'?province().fullName+'（全省）':S.vitalRegion==='ALL'?province().scope+'合计':city(S.vitalRegion)?.name||'未选择地区';
const vitalRecords=()=>VITAL.rows.filter(r=>r.province===S.province&&r.region===S.vitalRegion&&r.basis===S.vitalBasis);
function vitalCheck(year){return VITAL.checks.find(c=>c.province===S.province&&c.region===S.vitalRegion&&c.year===year);}
function vitalYears(){return Array.from({length:S.to-S.from+1},(_,i)=>{const year=S.from+i,record=vitalRecords().find(r=>r.year===year);return {year,record,status:year>VITAL.lastCompleteYear?'全年尚未结束':record?vstatus(record):vitalCheck(year)?.reason||'未取得所选地区、年份及口径数据'};});}
function vitalSource(k,compact=false){const s=VITAL.sources[k];if(!s)return '未取得来源';const detail=`<small class="source-note">${{official:'官方原文',official_account:'官方账号',media:'媒体刊载／转述',secondary:'民间转录／镜像·待复核'}[s.kind]} · ${esc(s.note)}；核查${VITAL.checked}</small>`;return `<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)} ↗</a>${s.offline?` <a href="${esc(s.offline)}" target="_blank" rel="noopener">离线原表 ↗</a>`:''}${compact?`<details><summary>出处与口径注释</summary>${detail}</details>`:detail}`;}

function vitalSources(){const review=VITAL.regionReviews?.[S.vitalRegion==='PROVINCE'?S.province+'-PROVINCE':S.vitalRegion];return [...new Set([...(review?.sources||[]),...vitalRecords().filter(r=>r.year>=S.from&&r.year<=S.to).flatMap(r=>[r.source,...(r.versions||[]).map(v=>v.source)])])];}
function vitalAlternative(){return `<div class="basis-links">${Object.entries(BASIS).map(([b,label])=>{const a=VITAL.rows.filter(r=>r.province===S.province&&r.region===S.vitalRegion&&r.basis===b&&r.year>=S.from&&r.year<=S.to);return `<button data-vital-basis="${b}" class="${b===S.vitalBasis?'selected':''}">${label} · ${a.length}年有指标</button>`;}).join('')}</div>`;}
function vitalPlot(...args){return dnMark(dnRaw_vitalPlot(...args),"mixed","历史已公布资料：实心为原文数，空心／虚线为原表推算或转述；缺失、待核断开，不是未来模拟。",{charts:true});}
function dnRaw_vitalPlot(rows){
 if(S.vitalBasis==='unspecified')return '<div class="empty"><b>口径未明确，不画连续可比趋势</b><p>下表保留原文指标及统计段落。常住、户籍或卫生登记范围尚未确认，不能把这些数值直接拼接比较。</p></div>';
 const rate=S.vitalMetric==='rate',keys=rate?['birthRate','deathRate']:['birth','death'],W=960,H=290,L=65,R=35,T=30,B=45,values=rows.flatMap(({record:r})=>r&&!r.flagged?keys.map(k=>r[k]).filter(finite):[]);
 if(!values.length)return `<div class="empty"><b>此区间未取得可绘制的${rate?'出生率、死亡率':'出生、死亡人数'}</b><p>可切换“人数／率”或人口口径。人数缺失不从率倒算；原文待核记录仅留在下表。</p></div>`;
 const max=Math.max(1,...values)*1.12,x=i=>L+(W-L-R)*(rows.length===1?.5:i/(rows.length-1)),y=v=>H-B-(H-T-B)*v/max;
 const grid=Array.from({length:5},(_,i)=>{const v=max*i/4;return `<line x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}" stroke="#e4e9df"/><text x="${L-10}" y="${y(v)+4}" text-anchor="end">${n(v,1)}</text>`;}).join('');
 const series=keys.map((key,j)=>rows.map(({record:r,year},i)=>{if(!r||r.flagged||!finite(r[key]))return '';const prev=rows[i-1]?.record,connect=i>0&&prev&&!prev.flagged&&finite(prev[key])&&!r.breakBefore&&prev.measure===r.measure&&prev.sourceComputed===r.sourceComputed&&VITAL.sources[prev.source].kind===VITAL.sources[r.source].kind;return `${connect?`<line data-series="${key}" x1="${x(i-1)}" y1="${y(prev[key])}" x2="${x(i)}" y2="${y(r[key])}" stroke="${j?'#d88c54':'#28675c'}" stroke-width="2.5" ${r.sourceComputed||VITAL.sources[r.source].kind==='media'?'stroke-dasharray="5 4"':''}/>`:''}<circle cx="${x(i)}" cy="${y(r[key])}" r="4" fill="${r.sourceComputed||VITAL.sources[r.source].kind==='media'?'white':j?'#d88c54':'#28675c'}" stroke="${j?'#d88c54':'#28675c'}"><title>${year} ${j?'死亡':'出生'}：${vf(r[key])}${rate?'‰':'万人'}${r.sourceComputed?'（原表推算）':VITAL.sources[r.source].kind==='media'?'（媒体转述）':''}</title></circle>`;}).join('')).join('');
 const step=Math.max(1,Math.ceil(rows.length/10)),ticks=rows.map(({year},i)=>i%step===0||i===rows.length-1?`<text x="${x(i)}" y="${H-12}" text-anchor="middle">${year}</text>`:'').join('');
 return `<svg class="vital-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(vitalRegionName())} ${BASIS[S.vitalBasis]} 历年出生死亡${rate?'率':'人数'}，缺失断开"><text x="8" y="18">${rate?'‰':'万人'}</text>${grid}${series}${ticks}</svg>`;
}
function vitalCatalog(){const a=VITAL.rows.filter(r=>r.province===S.province),keys=[...new Set(a.map(r=>r.source))];return `<section class="panel"><h2>${province().name} · 历年出生死亡资料</h2><p>${a.length}条年度／口径记录，覆盖${Math.min(...a.map(r=>r.year))}—${Math.max(...a.map(r=>r.year))}年中的部分年份；人数、比率和口径完整程度不同，不能当作连续完整序列。</p><button data-nav="vital">进入历年出生与死亡 →</button><details><summary>查看所选省份年度来源</summary>${keys.map(k=>`<article class="source-entry">${vitalSource(k)}</article>`).join('')}</details></section>`;}
function vitalCoverage(){return `<details class="panel" id="vitalCoverage"><summary>全省及各市 · 近十年补齐情况（2016—2025）</summary><p>同一年有多个口径时分别计数，不能相加。未明确口径和原表推算不算“已核实同口径直接人数”。点击地区查看原表与缺项。</p><div class="table-scroll"><table><thead><tr><th>地区</th><th>常住：人数齐／有指标</th><th>户籍：人数齐／有指标</th><th>未明确口径</th><th>任何口径均无指标的年份</th></tr></thead><tbody>${[['PROVINCE','全省'],...cities().map(c=>[c.id,c.name])].map(([id,label])=>{const a=VITAL.rows.filter(r=>r.province===S.province&&r.region===id&&r.year>=2016&&r.year<=2025),s=b=>{const q=a.filter(r=>r.basis===b);return q.filter(directCounts).length+'／'+q.length;},missing=Array.from({length:10},(_,i)=>2016+i).filter(y=>!a.some(r=>r.year===y));return `<tr><td><button data-vital-region="${id}">${label} →</button></td><td>${s('resident')}</td><td>${s('hukou')}</td><td>${a.filter(r=>r.basis==='unspecified').length}年</td><td>${missing.join('、')||'无；仍须查看字段及口径缺项'}</td></tr>`;}).join('')}</tbody></table></div></details>`;}
function vitalDetails(r){return `${r.measure?`<p class="hint"><b>统计事件：</b>${esc(r.measure)}</p>`:''}${r.note?`<details><summary>统计限制／待核说明</summary><p class="hint">${esc(r.note)}</p></details>`:''}${r.sourceComputed?'<b class="source-note">原表公式推算值 · 不是APP补值</b>':''}${r.originalText?`<details><summary>查看原文统计段落</summary><p>${esc(r.originalText)}</p></details>`:''}${r.versions?.length?`<details class="vital-versions"><summary>另有${r.versions.length}个版本／段落，展开对照</summary>${r.versions.map(v=>`<article><p>出生${vf(v.birth)}万人；死亡${vf(v.death)}万人；出生率${vf(v.birthRate)}‰；死亡率${vf(v.deathRate)}‰；自然增长率${vf(v.naturalRate)}‰。</p>${vitalSource(v.source)}<p>${esc(v.note||'旧发布值保留供核查，不与首选版混用。')}</p>${v.originalText?`<p>${esc(v.originalText)}</p>`:''}</article>`).join('')}</details>`:''}`;}
function vitalReview(){const r=VITAL.regionReviews?.[S.vitalRegion==='PROVINCE'?S.province+'-PROVINCE':S.vitalRegion];return `<section class="panel vital-review"><h2>本地区补查结果</h2><p>${esc(r?.note||'合计范围没有完整同口径序列，不用部分城市拼算；请切换单个城市查看核查结果。')}</p>${S.vitalBasis==='hukou'?'<p class="hint"><b>户籍不等于当年实际发生：</b>资料可能按出生申报、上户、死亡注销统计，可能含迟报或往年死亡销户。请看表中“统计事件”；不能直接解释为常住人口的出生死亡。</p>':''}${r?`<details><summary>核查依据 · ${r.checked}</summary>${r.sources.map(k=>`<article class="source-entry">${vitalSource(k)}</article>`).join('')}</details>`:''}</section>`;}
function vitalPage(){
 const all=vitalRecords(),rows=vitalYears(),known=rows.filter(x=>x.record),complete=known.filter(x=>directCounts(x.record)),latest=[...complete].sort((a,b)=>b.year-a.year)[0]?.record,years=Array.from({length:78},(_,i)=>1949+i),yearOptions=y=>years.map(i=>`<option value="${i}" ${i===y?'selected':''}>${i}</option>`).join(''),regionOptions=[['PROVINCE',province().fullName+'（全省）'],['ALL',province().scope+'合计（未取得完整同口径序列）'],...cities().map(c=>[c.id,c.name])];
 return title('03 / BIRTHS & DEATHS','历年出生与死亡','常住、户籍和未明确口径分开；登记注销与当年发生分别说明。')+`<div class="panel controls vital-controls"><label>省份<select id="provinceSelect">${Object.entries(REGISTRY.provinces).map(([id,p])=>`<option value="${id}" ${S.province===id?'selected':''}>${p.fullName}</option>`).join('')}</select></label><label>统计地区<select id="vitalRegion">${regionOptions.map(([id,label])=>`<option value="${id}" ${S.vitalRegion===id?'selected':''}>${label}</option>`).join('')}</select></label><label>人口口径<select id="vitalBasis">${Object.entries(BASIS).map(([id,label])=>`<option value="${id}" ${S.vitalBasis===id?'selected':''}>${label}</option>`).join('')}</select></label><label>起始年份<select id="vitalFrom">${yearOptions(S.from)}</select></label><label>结束年份<select id="vitalTo">${yearOptions(S.to)}</select></label></div>${vitalAlternative()}<div class="note warning"><b>${esc(vitalRegionName())} · ${BASIS[S.vitalBasis]}。</b>全省不能代替市级。出生减死亡只代表自然增减，不包含净迁移与统计调整。率是每千人口，不是总和生育率。2026全年尚未结束。</div>${vitalReview()}${vitalCoverage()}<section class="panel"><div class="panel-head"><h2>1949—2026 · 资料覆盖</h2><span>${known.length}/${rows.length}年有指标；${complete.length}年原文人数齐（不含转述、待核及推算）</span></div><p class="hint">绿色：官方原文人数齐；黄色：仅率／部分人数／参考或待核；灰色：此口径未取得。点击年份看原文。不同早期行政区划与统计制度仍可能不可比。</p><div class="year-coverage">${years.map(y=>{const r=all.find(r=>r.year===y);return `<button data-vital-year="${y}" class="${y>2025?'pending':r?directCounts(r)?'available':'partial':'unavailable'} ${y>=S.from&&y<=S.to?'in-range':''}" title="${y} ${y>2025?'全年未结束':vstatus(r)}">${y}</button>`;}).join('')}</div></section>${latest?`<div class="stats"><article class="stat"><span>${latest.year} · 最新人数齐备记录：出生（原口径）</span><strong>${vf(latest.birth)}万人</strong><small>${BASIS[S.vitalBasis]} · ${VITAL.sources[latest.source].kind==='secondary'?'民间参考值':VITAL.sources[latest.source].kind==='media'?'媒体刊载／转述':'官方资料'}</small></article><article class="stat"><span>${latest.year} · 死亡</span><strong>${vf(latest.death)}万人</strong><small>${S.vitalBasis==='hukou'?'户籍注销数可能含往年；未拆死亡原因':'按来源口径；未拆正常／非正常死亡'}</small></article><article class="stat"><span>${latest.year} · 出生减死亡</span><strong>${vf(latest.birth-latest.death,true)}万人</strong><small>四舍五入尾差保留；不代表总人口增减</small></article></div>`:''}<section class="panel vital-chart"><div class="panel-head"><h2>${esc(vitalRegionName())} · ${S.from}—${S.to}</h2><div class="segmented"><button data-vital-metric="count" class="${S.vitalMetric!=='rate'?'selected':''}">人数 · 万人</button><button data-vital-metric="rate" class="${S.vitalMetric==='rate'?'selected':''}">出生率／死亡率 · ‰</button></div></div><div class="legend"><span><i style="background:#28675c"></i>出生${S.vitalMetric==='rate'?'率':'人数'}</span><span><i style="background:#d88c54"></i>死亡${S.vitalMetric==='rate'?'率':'人数'}</span><span>空心／虚线：原表公式推算或媒体转述；缺失、待核及来源制度切换处断开</span></div>${vitalPlot(rows)}<div class="table-scroll"><table class="numeric vital-table"><thead><tr><th>年份</th><th>出生<br>万人</th><th>死亡<br>万人</th><th>出生−死亡<br>万人</th><th>出生率<br>‰</th><th>死亡率<br>‰</th><th>自然增长率<br>‰</th><th>状态／来源与原文</th></tr></thead><tbody>${[...rows].reverse().map(({year,record:r,status})=>`<tr data-vital-row="${year}"><td>${year}</td>${r?[r.birth,r.death,fullCounts(r)?r.birth-r.death:null,r.birthRate,r.deathRate,r.naturalRate].map((v,i)=>`<td>${vf(v,i===2)}</td>`).join(''):'<td colspan="6">— 未取得；不补零</td>'}<td>${r?`<span class="badge ${r.flagged||r.basis==='unspecified'||VITAL.sources[r.source].kind==='secondary'?'warn':''}">${vstatus(r)}${r.basis==='unspecified'?' · 不作同口径比较':''}</span>${vitalSource(r.source,true)}${vitalDetails(r)}`:`<span class="badge missing">${esc(status)}</span>`}</td></tr>`).join('')}</tbody></table></div><p class="hint">“—”是缺项，数值0才代表原文公布为零。人数保留两位小数展示，导出保留原始精度；原单位为人时仅换算为万人。三项率直接引用来源，不强行改写为相减值。原表推算不等于逐人统计。原文待核的出生−死亡仅是原数算术，不解释为真实自然增减。</p></section><section class="panel"><h2>读数边界与版本变化</h2><p>湖南2025年鉴对2011—2019年常住人口变动率作七普修订，旧公报值展开可查；1950—2010历史表各年口径未明，放在“口径未明确”。广州2024年鉴精确人数与早期公报舍入值分别保留。</p><p>长沙、邵阳2017年有往年死亡未销户集中清理，不能理解成当年死亡激增。肇庆2019年更换数据提供部门，序列在此断开。惠州2024原表混合来源及益阳、湘西原文疑点均标明，不擅自改单位或小数点。</p><p>仍缺部分市州年份、明确口径及死亡原因分类。核查过公报未取得指标，不代表从未发布；年度缺项及读取限制见逐年状态。城市零散数据不拼成九市／十四市州合计；本页不随未来情景改变。</p><p class="hint">本轮核查${VITAL.checked}。出生人数、出生率、总和生育率是不同指标；生产事故或医疗死亡不能替代全因死亡。两省全省新版已使用历年出生死亡重建基线；市州旧研究仍未据本页重建。</p></section>`;
}
function exportVital(){return [['省份','地区','口径','年份','出生_万人','死亡_万人','出生减死亡_万人','出生率_‰','死亡率_‰','自然增长率_‰','状态','来源等级','原表推算','原文待核','来源','URL','说明','原文','其他版本','统计事件','本地区补查结果'],...vitalYears().map(({year,record:r,status})=>[province().name,vitalRegionName(),BASIS[S.vitalBasis],year,r?.birth??'',r?.death??'',fullCounts(r)?Number((r.birth-r.death).toFixed(8)):'',r?.birthRate??'',r?.deathRate??'',r?.naturalRate??'',status,r?VITAL.sources[r.source].kind:'',r?.sourceComputed?'是':'',r?.flagged?'是':'',r?VITAL.sources[r.source].name:'',r?VITAL.sources[r.source].url:'',r?[r.note,VITAL.sources[r.source].note].filter(Boolean).join('；'):'不补零、不插值、不从率倒算',r?.originalText||'',r?.versions?JSON.stringify(r.versions):'',r?.measure||'按原文，发生/登记时点未逐项说明',VITAL.regionReviews?.[S.vitalRegion==='PROVINCE'?S.province+'-PROVINCE':S.vitalRegion]?.note||'未取得合计'])];}
function chooseVitalBasis(){const a=VITAL.rows.filter(r=>r.province===S.province&&r.region===S.vitalRegion&&r.year>=S.from&&r.year<=S.to);S.vitalBasis=['resident','hukou','unspecified'].find(b=>a.some(r=>r.basis===b))||'resident';}

function timeline(){return `<div class="toolbar"><div class="timeline" role="group" aria-label="四阶段年份">${YEARS.map(y=>`<button data-year="${y}" class="${S.year===y?'selected':''}" aria-pressed="${S.year===y}">${y}</button>`).join('')}</div><small>四年同时对照；选中年份同时更新地图和摘要</small></div>`;}
function legend(bands=BANDS){return `<div class="legend">${bands.map(([name,,,color])=>`<span><i style="background:${color}"></i>${name}</span>`).join('')}</div>`;}
function stack(values,bands,scale,label){return `<span class="stack" role="img" aria-label="${esc(label)}">${values.map((v,i)=>`<i title="[未来情景模拟] ${bands[i][0]}：${wan(v)}人" style="width:${v/scale*100}%;background:${bands[i][3]}"></i>`).join('')}</span>`;}
function charts(...args){return dnMark(dnRaw_charts(...args),"future","2026—2056均为未来情景模拟（含2026）；不是官方预测。细年龄重建仅是模型输入。",{charts:true,tables:true});}
function dnRaw_charts(id=S.city,careFirst=false){const ds=YEARS.map(y=>stats(id,y)),maxPop=Math.max(...ds.map(d=>d.total)),maxNeed=Math.max(...ds.map(d=>d.need));
 const pop=`<section class="chart-section population-chart"><div class="panel-head"><h3>人口结构 · 四阶段</h3><div class="segments"><button data-unit="count" class="${S.unit==='count'?'selected':''}" aria-pressed="${S.unit==='count'}">人数规模</button><button data-unit="share" class="${S.unit==='share'?'selected':''}" aria-pressed="${S.unit==='share'}">年龄占比</button></div></div><p class="hint">${S.unit==='count'?'四条共用最大总人口为尺度，长度比较人数。':'每条统一100%，只比较结构；总人数另列。'} 悬停色块看分龄人数。</p>${legend()}${ds.map(d=>`<div class="chart-row ${d.year===S.year?'current':''}" data-pop-year="${d.year}"><strong>${d.year}</strong><div class="stack-wrap">${stack(d.bands,BANDS,S.unit==='count'?maxPop:d.total,`${d.year}人口${wan(d.total)}人；`+BANDS.map(([n],i)=>n+wan(d.bands[i])+'人').join('；'))}</div><span><b>${wan(d.total)}人</b><small>60+ ${n(d.senior/d.total*100)}%</small></span></div>`).join('')}</section>`;
 const care=`<section class="chart-section care-chart"><h3>照护参考人数 · 来自哪些年龄组</h3>${legend(BANDS.slice(5))}<p class="hint">四条共用最大照护人数为尺度；色块是年龄贡献，不是居家／机构养老方式占比。</p>${ds.map((d,i)=>`<div class="chart-row ${d.year===S.year?'current':''}" data-care-year="${d.year}"><strong>${d.year}</strong><div class="stack-wrap">${stack(d.needBands,BANDS.slice(5),maxNeed,`${d.year}照护参考${wan(d.need)}人；`+BANDS.slice(5).map(([n],j)=>n+wan(d.needBands[j])+'人').join('；'))}</div><span><b>${wan(d.need)}人</b><small>${i?'较前十年 '+delta(d.need-ds[i-1].need):'情景起点，非实测'}</small></span></div>`).join('')}<p class="hint">60—69岁×6.9%、70—79岁×12.6%、80+×29.2%。90+仍用80+比例，60岁以下未纳入不代表没有需求。</p></section>`;
 return `<section class="panel profile-charts" data-region="${id}"><div class="panel-head"><h2>${esc(regionName())} · 一眼看变化</h2><span class="badge warn">情景估算</span></div>${careFirst?care+pop:pop+care}<details class="period-detail"><summary>图表数值、计算口径和来源</summary>${ageTable(ds)}${source('paper')}${source('survey')}</details></section>`;}
function ageTable(...args){return dnMark(dnRaw_ageTable(...args),"future","2026—2056均为未来情景模拟（含2026）；不是官方预测。细年龄重建仅是模型输入。",{charts:true,tables:true});}
function dnRaw_ageTable(ds=YEARS.map(y=>stats(S.city,y))){const rows=[['总人口',d=>d.total],...BANDS.map(([name],i)=>[name,d=>d.bands[i]]),['60+合计',d=>d.senior],['其中65+',d=>d.old],['其中80+',d=>d.oldest],...BANDS.slice(5).map(([name],i)=>[name+'照护参考',d=>d.needBands[i]]),['照护参考合计',d=>d.need]];return `<div class="table-scroll"><table class="numeric age-table"><thead><tr><th>指标 · 万人</th>${YEARS.map(y=>`<th>${y}</th>`).join('')}<th>30年增减</th></tr></thead><tbody>${rows.map(([name,get])=>`<tr><td>${name}</td>${ds.map(d=>`<td>${n(get(d)/1e4)}</td>`).join('')}<td>${signed((get(ds[3])-get(ds[0]))/1e4)}</td></tr>`).join('')}</tbody></table></div><p class="hint">九个年龄组互不重叠；60/65/80+是包含关系，不重复相加。按原数计算后显示取整，表面合计可能有尾差。</p>`;}
function verdict(...args){return dnMark(dnRaw_verdict(...args),"future","2026—2056均为未来情景模拟（含2026）；不是官方预测。细年龄重建仅是模型输入。",{block:true});}
function dnRaw_verdict(id=S.city){if(gdFull(id))return gdPopulationConclusion();if(hnFull(id))return hnPopulationConclusion();const a=stats(id,2026),b=stats(id,2056),changes=BANDS.map(([name],i)=>({name,delta:b.bands[i]-a.bands[i],need:i<5?null:b.needBands[i-5]-a.needBands[i-5]})),up=changes.filter(d=>d.delta>0).sort((x,y)=>y.delta-x.delta)[0],down=changes.filter(d=>d.delta<0).sort((x,y)=>x.delta-y.delta)[0],driver=changes.filter(d=>d.need!==null).sort((x,y)=>Math.abs(y.need)-Math.abs(x.need))[0],c=['ALL','PRD'].includes(id)?null:city(id);
 return `<section class="panel conclusion"><h2>${esc(regionName())} · 未来30年结论</h2><p><b>人口：</b>2026的${wan(a.total)}人变为2056的${wan(b.total)}人，增减${delta(b.total-a.total)}；60+占比${n(a.senior/a.total*100)}% → ${n(b.senior/b.total*100)}%。${up?`增加最多：${up.name}（${delta(up.delta)}）`:'各年龄组均未增加'}；${down?`减少最多：${down.name}（${delta(down.delta)}）`:'各年龄组均未减少'}。</p><p><b>照护：</b>参考人数${wan(a.need)} → ${wan(b.need)}人，净变化${delta(b.need-a.need)}；变化绝对贡献最大的是${driver.name}（${delta(driver.need)}）。这是固定困难率的算术拆分，不能当作健康恶化或缺床的证明。</p><p><b>服务关注：</b>${c?esc(c.focus):'分别核对居家日常照护、专业护理、费用可负担性与区县匹配。各城市证据见服务页。'}${c?' '+(c.staff.kind==='unknown'?'本地证据不足，以下仅为待核方向；':c.staff.kind==='historical'?'历史研究提示，当前是否持续待核；':'已有问题／政策信号；')+esc(c.staff.issue):''}</p>${c?source(c.issueSource):''}<p class="hint"><b>不能确定：</b>同年分级需求、家庭照护、有效服务工时与未来供给未齐，实际缺口未知。出生、死亡、迁移与跨年龄组流量未完整接入，原因贡献尚不能量化。${c?.mappingNote?esc(c.mappingNote):''}</p></section>`;}
function stageSummary(...args){return dnMark(dnRaw_stageSummary(...args),"future","2026—2056均为未来情景模拟（含2026）；不是官方预测。细年龄重建仅是模型输入。",{block:true});}
function dnRaw_stageSummary(){const d=stats(S.city,S.year);return `<div class="stats"><div class="stat">${S.year} · 研究总人口<strong>${wan(d.total)}人</strong><small>${esc(regionName())}，非实时统计</small></div><div class="stat">60岁及以上<strong>${wan(d.senior)}人</strong><small>占人口${n(d.senior/d.total*100)}%；80+ ${wan(d.oldest)}人</small></div><div class="stat">自理困难参考人数<strong>${wan(d.need)}人</strong><small>全国2021比例外推；全量实际失能人数未知</small></div></div>`;}
function keyConclusions(){return `<div class="three decade-conclusions">${YEARS.slice(1).map((end,i)=>{const o=rankings(i,'oldPP'),q=rankings(i,'needDelta'),ot=o.filter(d=>d.oldPP===o[0].oldPP),qt=q.filter(d=>d.needDelta===q[0].needDelta);return `<article class="stage-card" data-key-year="${YEARS[i]}"><h3>${YEARS[i]}—${end}</h3><p><b>${o[0].oldPP>0?'老龄化最快':'60+占比变化值最高'}：${ot.map(c=>c.name).join('、')}，${signed(o[0].oldPP)}个百分点。</b></p><p><b>${q[0].needDelta>0?'照护参考增量最多':'照护参考变化值最高'}：${qt.map(c=>c.name).join('、')}，${delta(q[0].needDelta)}。</b></p><p class="hint">${[...new Map([...ot,...qt].map(c=>[c.id,c])).values()].map(c=>esc(c.name+'：'+c.focus)).join('；')}。服务是否短缺仍需本地证据。</p><button data-period-open="${i}">看这个十年的全部城市 ↓</button></article>`;}).join('')}</div>`;}
function comparisons(){return modelAudit();}
function dnRaw_comparisons(){return modelAudit();}
function decadeDetail(...args){return dnMark(dnRaw_decadeDetail(...args),"future","2026—2056均为未来情景模拟（含2026）；不是官方预测。细年龄重建仅是模型输入。",{charts:true,tables:true});}
function dnRaw_decadeDetail(){return `<details class="panel"><summary>${esc(regionName())} · 展开逐十年年龄增减与照护贡献</summary>${YEARS.slice(1).map((end,i)=>{const d=periodData(S.city,i);return `<article class="readout"><h3>${d.start}—${d.end}</h3><p>人口增减${delta(d.totalDelta)}；60+占比变化${signed(d.oldPP)}个百分点；照护参考增减${delta(d.needDelta)}。</p><div class="table-scroll"><table class="numeric"><thead><tr><th>年龄 · 万人</th><th>${d.start}</th><th>${d.end}</th><th>人数增减</th><th>占比变化<br>百分点</th><th>照护增减</th></tr></thead><tbody>${BANDS.map(([name],j)=>`<tr><td>${name}</td><td>${n(d.a.bands[j]/1e4)}</td><td>${n(d.b.bands[j]/1e4)}</td><td>${signed((d.b.bands[j]-d.a.bands[j])/1e4)}</td><td>${signed((d.b.bands[j]/d.b.total-d.a.bands[j]/d.a.total)*100)}</td><td>${j<5?'未纳入':signed((d.b.needBands[j-5]-d.a.needBands[j-5])/1e4)}</td></tr>`).join('')}</tbody></table></div></article>`;}).join('')}<p class="hint">同龄组跨期变化不等于同一代人的变化；模型流量不等于现实因果；两省全省新版逐年流量见导出，市州旧研究未作对应分解。60岁以下照护未纳入，不按“没有需求”处理。</p></details>`;}
function actualBaseline(...args){return dnMark(dnRaw_actualBaseline(...args),"actual","2020年11月1日普查原数及公报舍入比例；不是未来模拟。",{tables:true,block:true});}
function dnRaw_actualBaseline(){const p=province(),total=cities().reduce((s,c)=>s+c.actual2020,0);return `<section class="panel baseline"><h2>2020普查事实 · ${p.scope}</h2><p>同一时点：2020年11月1日零时，常住人口口径。覆盖城市合计${wan(total)}人；${S.province==='GD'?'广东全省与珠三角九市范围不同。':province().name+province().scope+'覆盖全省。'}</p><div class="table-scroll"><table class="numeric"><thead><tr><th>城市</th><th>常住人口 · 人</th><th>0—14岁</th><th>15—59岁</th><th>60+</th><th>其中65+</th></tr></thead><tbody>${cities().map(c=>`<tr><td><button data-actual-city="${c.id}">${c.name} · 看资料与限制 →</button></td><td>${n(c.actual2020,0)}</td>${c.ratios2020.map(v=>`<td>${Number.isFinite(v)?n(v,2)+'%':'未取得'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="hint">年龄占比为公报四舍五入值，不由三大组编造更细年龄或未来人口。</p>${S.province==='GX'?source('gxcensus'):S.province==='HN'?source('hnpop')+source('hnage'):`<a href="${esc(REGISTRY.provinces.GD.actualSource)}" target="_blank" rel="noopener">广东七普人口来源 ↗</a>`}</section>`;}
function modelAudit(){return '<p class="note">公开版只提供三省区省级模拟。市级未来数据因官方修正版尚未完成核对而未收录；不计算市级未来排名。城市实际资料继续按原时点展示。</p>';}
function populationPage(){return title('01 / POPULATION','人口怎么变',`${province().name} · ${province().scope}，四阶段同口径对照`)+controls()+`<p class="history-entry"><button data-nav="vital">查看历年出生与死亡 →</button><button data-nav="care">查看全省养老金收支 →</button><small>出生死亡为历史统计；照护参考不用于判断养老金是否够发。</small></p>`+timeline()+`<div class="segments"><button data-view="scenario" class="${S.view==='scenario'?'selected':''}">2026—2056情景</button><button data-view="actual" class="${S.view==='actual'?'selected':''}">2020普查事实</button></div>`+(S.view==='actual'?actualBaseline():warning()+stageSummary()+charts()+verdict()+decadeDetail()+comparisons()+modelAudit());}
function serviceCard(c){const e=c.care,w=c.staff,g=c.institutionList;return `<section class="panel city-service" data-service-city="${c.id}"><div class="panel-head"><h2>${c.name} · 现实服务能否接得住</h2>${badge(c)}</div><p><b>实际缺口：未知。</b>${esc(e.judgment)}</p>${g?`<div class="note"><b>原始名录有记录：</b>${n(g.records,0)}条，填报“床位总数”合计${n(g.beds,0)}张；${g.missingBeds}条床位缺项，去除完全重复记录${g.duplicates}条。仅2025-01-30名录汇总，不能视为当前运营机构数、养老专用床位或有效供给。</div>${source('hnlist')}`:''}<div class="evidence-grid"><article><span class="badge ${e.occupancy.rate===null?'missing':''}">入住／使用 · 原时点</span><h3>${e.occupancy.rate===null?'精确入住率未取得':n(e.occupancy.rate)+'% · 来源快照'}</h3><p>${esc(e.occupancy.date)} · ${esc(e.occupancy.scope)}</p><details><summary>范围与来源</summary><p>${esc(e.occupancy.detail)}</p>${source(e.occupancy.source)}</details></article><article><span class="badge ${e.fee.weak?'warn':''}">${e.fee.amount==='未取得'?'收费缺项':e.fee.weak?'收费线索 · 待核':'公开收费样本'}</span><h3>${esc(e.fee.amount)}</h3><small>费用单位元/人/月；分档机构数另标</small><p>${esc(e.fee.kind)}；不是全市州均价</p><details><summary>包含什么、适用谁</summary><p>${esc(e.fee.detail)}</p>${source(e.fee.source)}</details></article><article><span class="badge missing">护理人力 · 非当班数</span><h3>${esc(w.staff)}</h3><p>实际护理班次与工时：未取得</p><details><summary>口径与来源</summary><p>${esc(w.staffNote)}</p>${source(w.source)}</details></article></div><div class="readout"><h3>已有需求／使用证据</h3><p>${esc(e.demand)}</p>${source(e.demandSource)}<h3>重点关注：${esc(c.focus)}</h3><p>${esc(w.issue)}</p>${source(c.issueSource)}<p><b>下一项缺口：</b>${esc(e.gap)}</p></div></section>`;}
function careOverview(){return stageSummary()+(S.city==='ALL'?`<section class="panel"><h2>先看需求，再核对服务</h2><p>60+人口不等于退休人口，自理困难人数不等于机构入住人数。未来需求变化见图解，现实缺口需同年分级需求、有效供给和支付能力。</p><div class="pill-row">${cities().map(c=>`<button data-city="${c.id}">${c.name} →</button>`).join('')}</div></section>`:'')+charts(S.city,true)+verdict()+`<section class="panel"><h2>${province().scope} · 服务证据覆盖</h2><div class="table-scroll"><table class="evidence-table coverage-table"><thead><tr><th>城市</th><th>已有资料</th><th>仍缺什么</th><th>服务关注</th></tr></thead><tbody>${cities().map(c=>`<tr><td><button data-city="${c.id}">${c.name} →</button></td><td>${c.institutionList?`2025-01-30名录${c.institutionList.records}条、填报床位${n(c.institutionList.beds,0)}张`:'分时点入住、收费及部分人员资料'}${source(c.institutionList?'hnlist':c.care.occupancy.source)}</td><td>${esc(c.care.gap)}</td><td>${badge(c)}<p>${esc(c.focus)}</p></td></tr>`).join('')}</tbody></table></div></section>`;}
function howPage(){const modes={home:['居家养老','本人、家庭与上门服务共同支持。核对家属可用时间、夜间照护、适老化和应急安排。'],community:['社区支持','助餐、日间照料、康复与短期喘息可与居家同时使用。核对距离、接送、服务时间和护理条件。'],institution:['机构照护','持续需求较多且家庭难以承担时比较机构。核对本人意愿、能力评估、收住条件、排班、费用和医疗衔接。']};return `<section class="panel"><h2>养老方式可以组合</h2><p>依据老人意愿、自理状况、家庭支持和预算选择；年龄不能单独决定方式。</p><div class="segments">${Object.entries(modes).map(([id,[name]])=>`<button data-how="${id}" class="${S.how===id?'selected':''}" aria-pressed="${S.how===id}">${name}</button>`).join('')}</div><div class="note"><b>${modes[S.how][0]}</b><p>${modes[S.how][1]}</p></div><p class="hint">缺本地去重使用人数与重叠关系，不画虚假的养老方式占比。</p></section>${chosenCities().map(c=>`<section class="panel"><h3>${c.name} · 居家与社区资料</h3><p>${esc(c.community)}</p>${source(c.communitySource)}</section>`).join('')}`;}
function moneyPage(){const key=S.province+'/'+S.city,draft=budgetDrafts[key]||{};return `<section class="panel"><h2>钱从哪里来，先看本人</h2><div class="three"><article><h3>养老金、保险与补助</h3><p>基本养老金、年金、保险与符合条件的津贴救助。领取地不等于居住地，参保数不能当退休人数。</p></article><article><h3>本人劳动与资产</h3><p>劳动经营、租金、利息与储蓄。没有本地可比收入分布时，不拿全市居民收入代替老人收入。</p></article><article><h3>家庭支持与照顾</h3><p>亲属给付和照护时间。未来是否能持续承担，还需家庭结构与实际调查。</p></article></div></section><section class="panel"><h2>已取得的经济来源证据</h2>${chosenCities().map(c=>`<article class="source-entry"><h3>${c.name}</h3><p>${esc(c.money)}</p>${source(c.moneySource)}</article>`).join('')}${S.province==='HN'?'<div class="note">省民政网络问卷中67.5%的受访家庭月支付意愿低于1000元；报告未列样本数与代表性。这不是全省老人收入、实际支付能力，更不能分配到各市州。</div>':''}</section><section class="panel"><h2>个人服务费预算</h2><p class="hint">仅在当前APP会话内按省份、城市分别保留，不套用地区平均值。</p><div class="three">${[['income','本人月收入'],['family','家庭每月支持'],['cost','养老服务月费']].map(([id,label])=>`<label class="field">${label}（元）<input data-budget="${id}" id="budget-${id}" type="number" min="0" step="100" value="${esc(draft[id]??'')}" placeholder="未知请留空，零可填0"></label>`).join('')}</div><div class="note" id="budgetResult" role="status"></div><button id="clearBudget">清空本地区预算</button><p class="hint">尚未扣除生活、医疗开支，未纳入物价、储蓄与负债，不能据此判断全市负担能力。</p></section>`;}
function supplyPage(){return `<section class="panel"><h2>有记录，不等于服务已经够用</h2><p>同时核对分级需求、可用人员、实际入住与轮候、费用和准入。培训人次不是在岗人数，登记床位不是有效服务能力，空床也不代表居家照护充足。</p></section>`+chosenCities().map(serviceCard).join('');}
function futurePage(){return charts(S.city,true)+verdict()+decadeDetail()+comparisons()+`<section class="panel"><h2>未来供给能否跟上？</h2><p>仍未取得与需求可配对的未来人员、床位、服务工时、家庭照护和资金规划，暂不计算“2056缺多少”。健康改善和家庭支持会改变实际购买服务需求。</p>${source('survey')}${source('paper')}</section>`;}
function servicesPage(){const tabs={overview:'养老总览',how:'如何养老',money:'经济来源',supply:'服务够不够',outlook:'未来需求'};return title('AUXILIARY / AGEING & CARE','照护服务资料（辅助）',`${province().name}：现实服务资料覆盖${province().scope}；人口范围以地区选择器为准，不据此计算真实服务缺口`)+controls()+timeline()+`<div class="segments care-tabs" role="group" aria-label="养老五个问题">${Object.entries(tabs).map(([id,name])=>`<button data-tab="${id}" class="${S.tab===id?'selected':''}" aria-pressed="${S.tab===id}">${name}</button>`).join('')}</div>`+(['overview','outlook'].includes(S.tab)?warning():'')+({overview:careOverview,how:howPage,money:moneyPage,supply:supplyPage,outlook:futurePage}[S.tab])();}
const shortProvince=name=>name.replace('维吾尔自治区','').replace('壮族自治区','').replace('回族自治区','').replace('自治区','').replace('特别行政区','').replace(/[省市]$/,'');
function sourcePage(){const relevant=new Set(['survey']);for(const c of cities())for(const id of[c.issueSource,c.moneySource,c.communitySource,c.staff.source,c.care.occupancy.source,c.care.demandSource,c.care.fee.source,c.actual2025Source])if(id)relevant.add(id);if(S.province==='HN')for(const id of['hnpop','hnage','hn2025','hnlist','hnneeds'])relevant.add(id);
 return title('DATA / SOURCES & LIMITS','数据与边界','实际、研究情景和未知各自标明；未接入地区不按零填充。')+controls(false)+`<details class="panel pension-source-catalog"><summary>养老金：实际基年、四阶段测算及政策来源</summary>${pensionSources()}</details>`+vitalCatalog()+`<section class="panel"><h2>覆盖情况</h2><table><thead><tr><th>地区</th><th>人口结构</th><th>未来情景</th><th>养老现实资料</th></tr></thead><tbody><tr><td>广东</td><td>珠三角9市2020普查及既有2025总量核对</td><td>广东全省：2025基线队列情景；九市：旧研究对照，不可混算</td><td>不同年份入住、费用、部分护理人员；缺全量需求与班次</td></tr><tr><td>湖南</td><td>14市州2020普查；2025省级统计</td><td>全省采用2025官方边际重建的队列情景；14市州仍为旧研究，不能加总替代新版全省</td><td>2025-01-30机构名录1768条，填报床位186231张；非当前运营供给。市州入住、人员、长期价缺项</td></tr><tr><td>其他省份</td><td colspan="3">未接入。地图可选择并查看覆盖状态，未显示虚构人口或缺口。</td></tr></tbody></table></section>${modelAudit()}<section class="panel"><h2>湖南新资料应怎样读</h2><p>机构表有单位名称、行政区划及床位字段，没有入住率、护理员、收费、护理等级和运营状态。APP仅聚合城市和床位，不展示负责人个人信息。原表合计不强行对齐2025年末统计公报的19.5万养老机构床位。</p><p>省民政网络问卷没有披露样本量与抽样代表性，不能作为各市州真实失能率；只用于提示核查居家照护、专业护理与支付问题。页面正文时间和URL路径日期不一致时，以正文及统计时点分别说明。</p><p>郴州原研究英文为Binzhou，按配套中文名及代码431000匹配；不误配山东滨州。</p><div class="links"><a href="evidence/hn-institutions.xlsx">下载湖南机构原表 ↗</a> · <a href="evidence/hn2025.pdf" target="_blank">湖南2025公报PDF ↗</a></div></section><section class="panel"><h2>${province().name} · 本页来源</h2>${[...relevant].map(id=>`<article class="source-entry">${source(id)}</article>`).join('')}</section><details class="panel legacy-archive"><summary>原广东历史与详细研究工具（离线保留）</summary><p>原V20已保留，包含历史出生死亡、同年护理人力表与原始证据。返回本页可继续地图入口。</p><button id="openLegacy">在本页展开原广东工具</button><div id="legacySlot"></div></details>`;}
function relevantSourceKeys(){const keys=new Set(['survey']);if(S.province==='GX')for(const key of Object.keys(GX_DATA.pensionVerification.sources))keys.add(key);for(const c of cities())for(const key of[c.issueSource,c.moneySource,c.communitySource,c.staff.source,c.care.occupancy.source,c.care.demandSource,c.care.fee.source,c.actual2025Source])if(key)keys.add(key);if(S.province==='HN')for(const key of['hnpop','hnage','hn2025','hnlist','hnneeds'])keys.add(key);return [...keys];}
function exportSources(){return [['查看省份','来源','链接','年份与范围'],...Object.values(PENSION.sources).map(s=>[province().name,s.name,s.url,s.date+'；'+s.note]),...relevantSourceKeys().map(key=>{const s=REGISTRY.sources[key];return [province().name,s.name,s.url,s.note]})];}
function exportPopulation(){return publicPopulationExport();}
function exportCare(){const rows=[['省份','城市','时点','指标','值','单位','性质与范围','来源']];for(const c of chosenCities()){
 if(c.institutionList)for(const [key,label]of[['records','机构名录记录数'],['beds','名录床位字段合计']])rows.push([province().name,c.name,'2025-01-30',label,c.institutionList[key],key==='beds'?'张':'条','原名录填报；不是当前运营或有效供给',REGISTRY.sources.hnlist.url]);
 for(const [label,value,id]of[['实际需求证据',c.care.demand,c.care.demandSource],['入住快照',JSON.stringify(c.care.occupancy),c.care.occupancy.source],['收费样本',JSON.stringify(c.care.fee),c.care.fee.source],['护理人员',c.staff.staff+'；'+c.staff.staffNote,c.staff.source],['服务关注',c.staff.issue+'；待补：'+c.care.gap,c.issueSource],['经济来源',c.money,c.moneySource]])rows.push([province().name,c.name,'时点见内容',label,value,'文字','不同年份范围，不计算全量服务缺口',REGISTRY.sources[id]?.url||'未取得']);
 for(const y of YEARS){const d=stats(c.id,y);for(const [label,value]of[['60+人口',d.senior],['80+人口',d.oldest],['照护参考',d.need],...BANDS.slice(5).map(([n],i)=>[n+'照护贡献',d.needBands[i]])])rows.push([province().name,c.name,y,label,value,'人',`生育${S.f}/迁移${S.m}研究情景；固定全国困难率，非实际`,REGISTRY.sources.paper.url+' ; '+REGISTRY.sources.survey.url]);}}
 return rows;}
function exportRankings(){return [['省份','城市','期初','期末','60+占比变化_百分点','照护参考增量_人','重点关注','证据状态','实际缺口','生育情景','迁移情景','性质','来源'],...rankings().map(c=>[province().name,c.name,c.start,c.end,c.oldPP,c.needDelta,c.focus,c.staff.issue,'未知',S.f,S.m,'未校准情景，非服务缺口排名',REGISTRY.sources[c.issueSource].url])];}
function csvDownload(rows,name){rows=dnExport(rows);const text='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出数据、性质与来源');}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.style.display='block';setTimeout(()=>el.style.display='none',2200);}
function render(){document.body.dataset.route=S.route;document.querySelector('#app').innerHTML=({map:uxMapPage,population:uxPopulationPage,care:uxPensionPage,compare:uxComparePage,lab:uxLabPage,services:servicesPage,vital:vitalPage,sources:sourcePage}[S.route]||uxMapPage)();document.querySelectorAll('nav [data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===S.route||(S.route==='services'&&b.dataset.nav==='care')));document.querySelector('#breadcrumb').textContent=(S.route==='map'?'全国':S.route==='vital'?vitalRegionName():S.route==='care'?province().name+'全省':province().name+' / '+(S.city==='ALL'?province().scope:city(S.city).name))+' / '+({map:'地图入口',population:'人口怎么变',care:'养老金能否接续',services:'照护服务（辅助）',vital:'历年出生与死亡',sources:'数据与边界'}[S.route]);document.querySelector('#export').disabled=S.route==='map';exportRows=uxExportForPage();if(S.route==='services'&&S.tab==='money')updateBudget();uxAfterRender();}
function updateBudget(){const key=S.province+'/'+S.city,values=['income','family','cost'].map(id=>document.querySelector('#budget-'+id)?.value),box=document.querySelector('#budgetResult');if(!box)return;if(values.some(v=>v===''||!Number.isFinite(Number(v))||Number(v)<0)){box.textContent='请填写三项非负金额；未知留空，缺失不按零计算。';return;}const [a,b,c]=values.map(Number),left=a+b-c;box.textContent=`个人预算：服务费后${left>=0?'剩余':'缺口'}${n(Math.abs(left),0)}元/月。尚未扣除其他生活、医疗开支。`;}
function setProvince(id){if(!REGISTRY.provinces[id])return;if(id!==S.province){S.vitalRegion='PROVINCE';S.vitalBasis='resident';}cityMemory[S.province]=S.city;S.province=id;S.city=cityMemory[id]||'ALL';S.mapCode=province().code;}
