function publicHome(){return uxHomeDisclaimer()+uxMainHead('A / 省份入口','选择省份，查看人口与养老金','只对广东、湖南、广西提供省级未来情景；市级保留已收录实际资料',uxControls(false))+`<section class="public-provinces" aria-label="三省区选择">${Object.entries(REGISTRY.provinces).map(([k,p])=>`<button data-map-code="${p.code}" aria-pressed="${S.province===k}" class="${S.province===k?'selected':''}"><small>已接入 · 省级模拟</small><h2>${p.fullName}</h2><span>市级实际资料：${p.scope}</span><b>${S.province===k?'当前所选':'选择地区 →'}</b></button>`).join('')}</section>${publicProvinceCard()}${uxYears()}<div class="ux-shortcuts"><button data-nav="compare">省级对照 →</button><button data-nav="lab">情景研究 →</button><button data-nav="vital">出生与死亡 →</button></div>${uxNotes()}`;}
function publicProvinceCard(){const p=province(),d=stats('ALL',S.year),a=qaLatestPopulation({prov:S.province,id:p.modelId,name:p.fullName});return `<section class="panel"><h2>${p.fullName} · 全省区范围</h2><div class="public-summary"><article>${dnTag('actual')}<h3>${a.year}年末常住人口</h3><strong>${n(a.population/1e4)} 万人</strong><p>固定实际统计，不随情景变化</p>${qaSources(a.sources)}</article><article>${dnTag('future')}<h3>${S.year}年情景人口</h3><strong>${n(d.total/1e4)} 万人</strong><p>60岁以上占比 ${n(d.senior/d.total*100)}%；非实际统计</p></article></div><button class="primary" data-enter="population">进入${p.name}全省区人口变化 →</button> <button data-enter="care">查看${p.name}养老金 →</button><p class="hint">广东全省不等于珠三角九市；城市实际数不与省级未来值混算。</p></section>`;}
function publicCityPage(){const c=city(S.city),latest=c?qaLatestPopulation({prov:S.province,id:c.id,name:c.name}):null;return title('CITY / 实际资料',c?c.name+' · 实际与缺项':'珠三角九市 · 实际与缺项',PUBLIC_LIMIT)+controls()+`<section class="panel"><h2>实际统计</h2>${latest?`<p>${latest.year}年末常住人口：${latest.population===null?'未取得':n(latest.population/1e4)+'万人'}${latest.weak?'（来源待复核）':''}</p>${qaSources(latest.sources)}`:''}<p>2020普查人口：${c?n(c.actual2020/1e4):n(cities().reduce((s,c)=>s+c.actual2020,0)/1e4)}万人。</p>${c?`<p>0—14岁 ${c.ratios2020[0]??'未知'}%；15—59岁 ${c.ratios2020[1]??'未知'}%；60岁以上 ${c.ratios2020[2]??'未知'}%。</p>`:''}<p>${dnTag('unknown')}2026／2036／2046／2056市级人口、老龄化和养老金缺口：未提供，不能判断。</p><button data-city="ALL">返回全省区模拟 →</button> <button data-view="actual">查看本省城市普查表 →</button> <button data-nav="vital">查出生死亡历史 →</button></section>`;}
