exportCare=function(){const rows=[['省份','城市','时点','指标','值','单位','性质与范围','来源']];for(const c of chosenCities()){for(const [label,value,id]of [['实际需求证据',c.care.demand,c.care.demandSource],['入住快照',JSON.stringify(c.care.occupancy),c.care.occupancy.source],['收费样本',JSON.stringify(c.care.fee),c.care.fee.source],['护理人员',c.staff.staff+'；'+c.staff.staffNote,c.staff.source],['经济来源',c.money,c.moneySource]])rows.push([province().name,c.name,'时点见内容',label,value,'文字','不同年份与范围；不代表当前全量供需',REGISTRY.sources[id]?.url||'未取得']);for(const y of YEARS)rows.push([province().name,c.name,y,'未来照护需求','未提供','人',PUBLIC_LIMIT,'']);}return rows;};
servicesPage=function(){const tabs={overview:'实际资料总览',how:'如何养老',money:'个人经济来源',supply:'服务供给资料',outlook:'未来需求限制'};return title('AUXILIARY / 实际服务','照护服务资料（辅助）','按原统计年份呈现，不等于养老金收支')+controls()+`<div class="segments">${Object.entries(tabs).map(([k,v])=>`<button data-tab="${k}" class="${S.tab===k?'selected':''}">${v}</button>`).join('')}</div>`+(S.tab==='how'?howPage():S.tab==='money'?moneyPage():S.tab==='outlook'?modelAudit()+(S.city==='ALL'?charts('ALL',true):''):supplyPage());};
sourcePage=function(){return title('SOURCES / 公开范围','数据来源与公开版限制','本包不附原文档案；访问原网站需要网络')+controls(false)+publicDisclaimer()+modelAudit()+`<section class="panel"><h2>三省区省级模拟的输入来源</h2><p>${[gdModelSources(),hnModelSources(),gxModelSources()].join(' ; ').split(' ; ').map(u=>rxLink(u,'原始发布')).join(' · ')}</p><p>城市实际资料覆盖广东九市、湖南14市州、广西14市；没有扩为全国完整数据库。历史年份缺项不插值，不把户籍与常住相加。</p></section>`+vitalCatalog()+`<details class="panel"><summary>养老金来源</summary>${Object.keys(PENSION.sources).map(pensionSource).join('')}</details><section class="panel"><h2>本省市级资料来源</h2>${relevantSourceKeys().map(k=>source(k)).join('')}</section>`;};
function publicPopulationExport(){const rows=[['省份','范围','地区','年份','指标','值','单位','性质与限制','来源']];const src=S.province==='GD'?gdModelSources():S.province==='HN'?hnModelSources():gxModelSources();if(S.city!=='ALL'){const c=city(S.city);if(c){rows.push([province().name,'城市',c.name,2020,'常住人口',c.actual2020,'人','实际统计；2020普查',rxActual(c.id).source2020]);const a=qaLatestPopulation({prov:S.province,id:c.id,name:c.name});rows.push([province().name,'城市',c.name,a.year,'最新已接入常住人口',a.population??'未取得','人',a.weak?'来源待核':a.population===null?'缺项／暂不能判断':'实际统计',a.sources.join(' ; ')]);}for(const y of YEARS)rows.push([province().name,'市级',c?.name||'珠三角九市合计',y,'未来人口','未提供','人',PUBLIC_LIMIT,'']);return rows;}for(const y of YEARS){const d=stats('ALL',y);for(const [label,v]of [['总人口',d.total],...BANDS.map(([name],i)=>[name,d.bands[i]]),['60岁以上合计',d.senior],['65岁以上',d.old],['80岁以上',d.oldest]])rows.push([province().name,'全省区',province().fullName,y,label,v,'人','未来情景模拟；2025细年龄为重建输入；生育'+S.f+'／迁移'+S.m+'；非官方预测',src]);}return rows;}
