const publicOriginalAfterRender=uxAfterRender;
uxAfterRender=function(){publicOriginalAfterRender();document.querySelector('#breadcrumb').textContent=document.querySelector('#breadcrumb').textContent.replace('全国地图','省份入口');document.querySelectorAll('a[href]').forEach(a=>{const href=a.getAttribute('href');if(href&&(/^(evidence|legacy-guangdong)\//.test(href)||/^(file:|[A-Z]:[\\/])/.test(href))){const note=document.createElement('span');note.className='hint';note.textContent='原文附件未随公开包分发，请使用本条官方来源链接。';a.replaceWith(note);}});};

document.addEventListener('click',e=>{const b=e.target.closest('button,[data-map-code]');if(!b)return;
 if(b.dataset.vitalRegion){S.vitalRegion=b.dataset.vitalRegion;S.from=2016;S.to=2025;chooseVitalBasis();render();window.scrollTo(0,0);return;}
 if(b.dataset.vitalMetric){S.vitalMetric=b.dataset.vitalMetric;render();return;}
 if(b.dataset.vitalBasis){S.vitalBasis=b.dataset.vitalBasis;render();return;}
 if(b.dataset.vitalYear){S.from=S.to=Number(b.dataset.vitalYear);render();document.querySelector('.vital-chart')?.scrollIntoView({block:'start'});return;}
 if(b.id==='viewProvinceVital'){S.vitalRegion='PROVINCE';S.vitalBasis='resident';render();return;}
 if(b.dataset.nav){go(b.dataset.nav);return;}
 if(b.dataset.mapCode){S.mapCode=String(b.dataset.mapCode);const match=Object.entries(REGISTRY.provinces).find(([,p])=>p.code===S.mapCode);if(match)setProvince(match[0]);render();return;}
 if(b.dataset.enter){go(b.dataset.enter);return;}
 if(b.dataset.year){S.year=Number(b.dataset.year);render();return;}
 if(b.dataset.unit){S.unit=b.dataset.unit;render();document.querySelector('.profile-charts')?.scrollIntoView({block:'start'});return;}
 if(b.dataset.actualCity){S.city=b.dataset.actualCity;cityMemory[S.province]=S.city;S.view='scenario';render();window.scrollTo(0,0);return;}
 if(b.dataset.city){S.city=b.dataset.city;cityMemory[S.province]=S.city;render();document.querySelector('.controls')?.scrollIntoView({block:'start'});return;}
 if(b.hasAttribute('data-period-open')){S.period=Number(b.dataset.periodOpen);render();openRanking();return;}
 if(b.hasAttribute('data-period')){S.period=Number(b.dataset.period);render();openRanking();return;}
 if(b.dataset.metric){S.metric=b.dataset.metric;render();openRanking();return;}
 if(b.dataset.view){S.view=b.dataset.view;render();return;}
 if(b.dataset.tab){S.tab=b.dataset.tab;render();return;}
 if(b.dataset.how){S.how=b.dataset.how;render();return;}
 if(b.id==='clearBudget'){delete budgetDrafts[S.province+'/'+S.city];render();return;}
 if(b.id==='exportRanking'){csvDownload(exportRankings(),`${province().name}_${YEARS[S.period]}-${YEARS[S.period+1]}_城市十年对比.csv`);return;}
 
});
document.addEventListener('keydown',e=>{const map=e.target.closest('[data-map-code]');if(map&&['Enter',' '].includes(e.key)){e.preventDefault();map.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='provinceSelect')setProvince(e.target.value);else if(id==='citySelect'){S.city=e.target.value;cityMemory[S.province]=S.city;}else if(id==='vitalRegion'){S.vitalRegion=e.target.value;chooseVitalBasis();}else if(id==='vitalBasis')S.vitalBasis=e.target.value;else if(id==='vitalFrom'){S.from=Number(e.target.value);if(S.from>S.to)S.to=S.from;}else if(id==='vitalTo'){S.to=Number(e.target.value);if(S.to<S.from)S.from=S.to;}else if(id==='fertility')S.f=e.target.value;else if(id==='migration')S.m=e.target.value;else return;render();});
